1	/*
2	 * boot_clock.c - BK7258 cold-start DPLL enable (product-grade).
3	 *
4	 * On cold reset the BootROM leaves EN_DPLL=0.  This module mirrors the
5	 * Armino SDK sys_hal_early_init analog-register sequence to enable and
6	 * calibrate the DPLL before jumping to the app, so the app can
7	 * deterministically switch the core mux to 320 MHz on both cold and soft
8	 * reset paths.
9	 *
10	 * Board chip_id = 0x23A40910 = PM_CHIP_ID_MP_C.  The SDK has no explicit
11	 * MP_C branch, so the default else-branch ANA_REG values apply
12	 * (sys_hal.c:2865-2876).
13	 *
14	 * Product-grade safety:
15	 *   - Skip the full sequence if EN_DPLL is already set (soft-reset path
16	 *     where the loader already enabled DPLL).
17	 *   - Every analog-SPI write has a bounded timeout (ANA_SPI_TIMEOUT); if
18	 *     any write times out, the remaining sequence is aborted and control
19	 *     returns to the caller.  The app's 26 MHz fallback handles the case
20	 *     where the DPLL ends up not enabled.
21	 *   - No step can hang the bootloader indefinitely.
22	 *
23	 * Scope: DPLL enable + SPI recalibration only.  Does NOT switch the core
24	 * mux (M1) or the flash clock (M2 cksel_flash) -- switching flash to the
25	 * 480 MHz source stalls on this board; the core mux is left for the app.
26	 *
27	 * Freestanding: no libc, no .data/.bss globals, only stack locals.
28	 */
29	
30	#include <stdint.h>
31	
32	/* ------------------------------------------------------------------ */
33	/* MMIO.                                                              */
34	/* ------------------------------------------------------------------ */
35	
36	#define REG32(addr)        (*(volatile uint32_t *)(addr))
37	
38	/* Analog register block (SYS_ANA_REG0 = 0x44010100, REGn = +4*n). */
39	
40	#define ANA_SPI_STATE      0x440100E8u
41	#define ANA_REG0           0x44010100u
42	#define ANA_REG2           0x44010108u
43	#define ANA_REG3           0x4401010Cu
44	#define ANA_REG5           0x44010114u
45	#define ANA_REG8           0x44010120u
46	#define ANA_REG9           0x44010124u
47	#define ANA_REG10          0x44010128u
48	#define ANA_REG11          0x4401012Cu
49	#define ANA_REG12          0x44010130u
50	#define ANA_REG13          0x44010134u
51	#define ANA_REG25          0x44010164u
52	
53	#define EN_DPLL_BIT        (1u << 5)
54	
55	/* Analog-SPI busy-wait timeout (iterations).  Sized so that even at the
56	 * slowest cold-start clock (26 MHz) a genuine SPI transfer completes
57	 * well within the budget, but a stuck state machine aborts in < 1 ms.
58	 */
59	
60	#define ANA_SPI_TIMEOUT    100000u
61	
62	/* UART1 polled output (matches boot_main.c). */
63	
64	#define UART1_FIFO         REG32(0x4583001Cu)
65	#define UART1_STATUS       REG32(0x45830018u)
66	#define UART1_TX_READY     (1u << 20)
67	
68	/* ------------------------------------------------------------------ */
69	/* Freestanding helpers (no libc, stack-only).                        */
70	/* ------------------------------------------------------------------ */
71	
72	static void clk_putc(char c)
73	{
74	    int i;
75	    for (i = 0; i < 100000; i++) {
76	        if (UART1_STATUS & UART1_TX_READY) break;
77	    }
78	    UART1_FIFO = (uint32_t)(uint8_t)c;
79	}
80	
81	static void clk_puts(const char *s)
82	{
83	    while (*s) clk_putc(*s++);
84	}
85	
86	static void clk_puthex(uint32_t v)
87	{
88	    static const char hex[] = "0123456789ABCDEF";
89	    int s;
90	    for (s = 28; s >= 0; s -= 4)
91	        clk_putc(hex[(v >> s) & 0xFu]);
92	}
