145	/* ------------------------------------------------------------------ */
146	/* DPLL SPI recalibration (sys_hal_cali_dpll, sys_hal.c:2659-2696).   */
147	/* Returns 0 on success, -1 on SPI timeout.                           */
148	/* ------------------------------------------------------------------ */
149	
150	static int boot_cali_dpll(void)
151	{
152	    /* Lower the SPI trigger and settle. */
153	
154	    if (ana_and(ANA_REG0, ~(1u << 19)) < 0)   /* spitrig = 0 */
155	        return -1;
156	    clk_delay(120);
157	
158	    /* Rising edge starts recalibration; gate unlock-detect during settle. */
159	
160	    if (ana_rmw(ANA_REG0, (1u << 4), (1u << 19)) < 0)  /* spitrig=1, spideten=0 */
161	        return -1;
162	    clk_delay(3400);
163	
164	    /* Re-enable detect (the SDK's de-facto "lock wait"). */
165	
166	    if (ana_or(ANA_REG0, (1u << 4)) < 0)      /* spideten = 1 */
167	        return -1;
168	    clk_delay(3400);
169	
170	    return 0;
171	}
172	
173	/* ------------------------------------------------------------------ */
174	/* Step functions — each returns 0 on success, -1 on failure.         */
175	/* ------------------------------------------------------------------ */
176	
177	static int step1_dpll_power(void)
178	{
179	    /* ANA_REG5: power up audpll briefly, enable DPLL + DCO, set adc_div,
180	     * re-power-down audpll. */
181	
182	    uint32_t v = REG32(ANA_REG5);
183	    v &= ~(1u << 13);                              /* PWDAUDPLL = 0 */
184	    v |= (1u << 5) | (1u << 3) | (1u << 2);       /* EN_DPLL | NC_3_3 | EN_DCO */
185	    if (ana_write(ANA_REG5, v) < 0) return -1;
186	    if (ana_rmw(ANA_REG5, (0x3u << 10), (0x1u << 10)) < 0) return -1;  /* adc_div */
187	    if (ana_or(ANA_REG5, (1u << 13)) < 0) return -1;  /* PWDAUDPLL = 1 */
188	    return 0;
189	}
190	
191	static int step2_band_dsptrig(void)
192	{
193	    /* ANA_REG0: band field, safe-mode replacement, dsptrig pulse. */
194	
195	    if (ana_or(ANA_REG0, (0x13u << 20)) < 0) return -1;   /* band = 0x13 */
196	    if (ana_write(ANA_REG0, 0xF1305B56u) < 0) return -1;  /* dpll_tsten=0 */
197	    if (ana_or(ANA_REG0, (1u << 26)) < 0) return -1;      /* dsptrig = 1 */
198	    if (ana_and(ANA_REG0, ~(1u << 26)) < 0) return -1;    /* dsptrig = 0 */
199	    return 0;
200	}
201	
202	static int step3_xtal_bias(void)
203	{
204	    /* ANA_REG2/3: xtal tuning and bias. */
205	
206	    if (ana_write(ANA_REG2, 0x7E003450u) < 0) return -1;  /* xtal ctune=0x50 */
207	    if (ana_write(ANA_REG3, 0xC5F00B88u) < 0) return -1;
208	    return 0;
209	}
210	
211	static int step4_latched_block(void)
212	{
213	    /* spi_latch1v on -> ANA_REG8/9/10-13/25 (default branch for MP_C) ->
214	     * ANA_REG3.inbufen0v9 -> latch off. */
215	
216	    if (ana_or(ANA_REG9, (1u << 9)) < 0) return -1;       /* spi_latch1v = 1 */
217	    if (ana_write(ANA_REG8,  0x57E62F26u) < 0) return -1;
218	    /* VDDIG raised from SDK default 0xB to 0xE (0.95 V) so the DPLL
219	     * can acquire a 480 MHz lock during the recalibration below.
220	     * The SDK sets 0xB in early_init then raises it later in
221	     * sys_hal_core_bus_clock_ctrl; we raise it upfront instead. */
222	
223	    if (ana_write(ANA_REG9,  0x787EC8A4u) < 0) return -1;
224	    if (ana_write(ANA_REG10, 0xC3D543A7u) < 0) return -1;
225	    if (ana_write(ANA_REG11, 0xB47E99F8u) < 0) return -1;
226	    if (ana_write(ANA_REG12, 0xB47ECF20u) < 0) return -1;
227	    if (ana_write(ANA_REG13, 0x727070EEu) < 0) return -1;
228	    if (ana_write(ANA_REG25, 0x0961FAA4u) < 0) return -1;
229	    if (ana_or(ANA_REG3, (1u << 6)) < 0) return -1;       /* inbufen0v9 = 1 */
230	    if (ana_and(ANA_REG9, ~(1u << 9)) < 0) return -1;     /* spi_latch1v = 0 */
231	    return 0;
232	}
233	
234	static int step5_recalibrate(void)
235	{
236	    clk_delay(120);
237	    return boot_cali_dpll();
238	}
239	
240	/* ------------------------------------------------------------------ */
241	/* Public: cold-start DPLL enable.                                    */
242	/*                                                                    */
243	/* Called from c_main() after UART init, before the FAL partition     */
244	/* scan.  Bounded and fail-safe: if any analog-SPI write times out,   */
245	/* the remaining sequence is aborted and control returns to c_main;   */
246	/* the app's 26 MHz fallback handles EN_DPLL=0.                       */
247	/* ------------------------------------------------------------------ */
248	
249	void boot_clock_cold_init(void)
250	{
251	    /* Guard: skip if DPLL already enabled (soft-reset / loader residue). */
252	
253	    if (REG32(ANA_REG5) & EN_DPLL_BIT)
254	        return;
255	
256	    /* Run the cold-init sequence.  Abort on any SPI-write timeout. */
257	
258	    if (step1_dpll_power() < 0 ||
259	        step2_band_dsptrig() < 0 ||
260	        step3_xtal_bias() < 0 ||
261	        step4_latched_block() < 0 ||
262	        step5_recalibrate() < 0)
263	    {
264	        clk_puts("BClk FAIL\r\n");
265	        return;
266	    }
267	
268	    /* Evidence: confirm EN_DPLL landed. */
269	
270	    clk_puts("BClk A5=");
271	    clk_puthex(REG32(ANA_REG5));
272	    clk_puts(" A9=");
273	    clk_puthex(REG32(ANA_REG9));
274	    clk_puts("\r\n");
275	}

