691	
692		pm_cpu_freq_e prev_freq = s_pre_cpu_freq;
693	
694		if(prev_freq == cpu_bus_freq)
695			return BK_OK;
696	
697		if(prev_freq > cpu_bus_freq)// eg: 480->60
698		{
699			sys_hal_switch_cpu_bus_freq_high_to_low(cpu_bus_freq);
700		}
701		else // eg: 60-480
702		{
703			sys_hal_switch_cpu_bus_freq_low_to_high(cpu_bus_freq);
704		}
705		s_pre_cpu_freq = cpu_bus_freq;
706		return ret;
707	}
