244	bk_err_t sys_drv_switch_cpu_bus_freq(pm_cpu_freq_e cpu_bus_freq)
245	{
246		uint32_t i;
247		bk_err_t ret = BK_FAIL;
248		pm_cpu_freq_e prev_freq = s_cpu_freq;
249	
250		if(prev_freq == cpu_bus_freq)
251			return BK_OK;
252	
253		switch(cpu_bus_freq)
254		{
255			case PM_CPU_FRQ_480M:
256			case PM_CPU_FRQ_320M:
257			case PM_CPU_FRQ_240M:
258			case PM_CPU_FRQ_120M:
259			case PM_CPU_FRQ_80M:
260			case PM_CPU_FRQ_60M:
261			case PM_CPU_FRQ_26M:
262				break;
263	
264			default:
265				return BK_FAIL;
266				break;
267		}
268	
269		uint32_t int_level = sys_drv_enter_critical();
270		if(prev_freq < cpu_bus_freq)
271		{
272			for(i = prev_freq + 1; i <= cpu_bus_freq; i ++)
273			{
274				ret = sys_hal_switch_cpu_bus_freq(i);
275			}
276		}
277		else
278		{
279			for(i = prev_freq - 1; i >= cpu_bus_freq; i --)
280			{
281				ret = sys_hal_switch_cpu_bus_freq(i);
282			}
283		}
284	
285		s_cpu_freq = cpu_bus_freq;
286		sys_drv_exit_critical(int_level);
287	
288		return ret;
289	}
