/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_clk_ll.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * BK7258 clock low-level register helpers shared by the boot-time
 * bring-up (bk7258_clock.c) and the runtime DVFS lower half
 * (bk7258_dvfs.c).  Everything here is `static inline` so the two
 * translation units can each include it without a multiple-definition
 * link conflict, and so the freestanding early-boot caller (no libc,
 * CPU at the BootROM 26 MHz residue clock) and the post-scheduler DVFS
 * caller share the exact same write/wait protocol.
 *
 * Mirrors the Armino SDK sys_ll analog-reg accessors
 * (sys_ll_set_ana_reg9_* / sys_ll_set_analog_reg_value) and the SDK
 * ctrl_vddd_h_vol / ctrl_vdddig_h_vol latch sequence (sys_hal.c:517-542).
 *
 * Register map (Armino soc/bk7258/soc/sys_reg.h + sys_hal.c):
 *   SYS block base        0x44010000
 *   ANA_SPI_STATE         0x440100E8  analog-SPI-write busy bit [idx]
 *                                       (idx = reg number; ANA_REG0 -> 0)
 *   CPU0_INT_HALT_CLK_OP  0x44010010  cpu0_speed [4]
 *   CPU_CLK_DIV_MODE1 M1 0x44010020  clkdiv_core [3:0], cksel_core [5:4]
 *   ANA_REG0              0x44010100
 *   ANA_REG5              0x44010114  EN_DPLL [5]
 *   ANA_REG9              0x44010124  spi_latch1v [9],
 *                                       vcorehsel (VDDIG) [16:19],
 *                                       vdighsel (VDDD)  [26:28]
 ****************************************************************************/

#ifndef __ARCH_ARM_SRC_BK7258_CHIP_BK7258_CLK_LL_H
#define __ARCH_ARM_SRC_BK7258_CHIP_BK7258_CLK_LL_H

#include <nuttx/config.h>
#include <stdint.h>

/* SYS register block. */
#define BK7258_SYS_BASE            0x44010000u
#define BK7258_ANA_SPI_STATE       (BK7258_SYS_BASE + 0x00e8u)
#define BK7258_CPU0_HALT_CLK_OP    (BK7258_SYS_BASE + 0x0010u)
#define BK7258_CPU_CLK_DIV_MODE1   (BK7258_SYS_BASE + 0x0020u)  /* M1 */
#define BK7258_ANA_REG0            (BK7258_SYS_BASE + 0x0100u)
#define BK7258_ANA_REG5            (BK7258_SYS_BASE + 0x0114u)
#define BK7258_ANA_REG9            (BK7258_SYS_BASE + 0x0124u)

/* M1 (CPU_CLK_DIV_MODE1) core-source fields. */
#define BK7258_M1_CLKDIV_MASK      0x0fu               /* clkdiv_core [3:0] */
#define BK7258_M1_CKSEL_MASK       (0x3u << 4)         /* cksel_core [5:4] */
#define BK7258_M1_CKSEL_SHIFT      4

/* CPU0_INT_HALT_CLK_OP: cpu0_speed [4] (1 = /2 of the core clock for CPU0;
 * SysTick is on the CPU0 processor clock). */
#define BK7258_CPU0_SPEED_BIT      (1u << 4)

/* ANA_REG5: EN_DPLL [5]. */
#define BK7258_ANA5_EN_DPLL        (1u << 5)

/* ANA_REG9 field bit positions (from sys_struct.h:1166,1172,1177 and
 * sys_ll.h:7249,7294 rmw encoders). */
#define BK7258_ANA9_SPI_LATCH1V    (1u << 9)
#define BK7258_ANA9_VDDDIG_SHIFT   16u                  /* vcorehsel [16:19] */
#define BK7258_ANA9_VDDDIG_MASK    (0xfu << BK7258_ANA9_VDDDIG_SHIFT)
#define BK7258_ANA9_VDDD_SHIFT     26u                  /* vdighsel  [26:28] */
#define BK7258_ANA9_VDDD_MASK      (0x7u << BK7258_ANA9_VDDD_SHIFT)

/* The ANA_REG SPI busy bit index matches the register number (ANA_REG0 -> 0,
 * ANA_REG5 -> 5, ANA_REG9 -> 9). */
#define BK7258_ANA_SPI_BUSY(idx)   (1u << (idx))

/* Settle delay after a VDDD/VDDIG change.  The SDK sits at the
 * SYS_SWITCH_VDDDIG_VOL_DELAY_TIME constant (~10 us for "cpu0 max freq
 * 240m").  We approximate with a bus-independent busy loop; this low-level
 * helper is shared by early boot (CPU ~26 MHz) and post-boot DVFS, so the
 * iteration count below is a conservative lower bound that covers the SDK's
 * 10 us even at the slowest relevant path. */
#define BK7258_CLK_DELAY_ITERS_PER_US  32u
#define BK7258_VDD_SETTLE_US          10u

/* Raw MMIO. */
#define BK7258_REG(a)               (*(volatile uint32_t *)(uintptr_t)(a))

/****************************************************************************
 * Inline helpers
 ****************************************************************************/

/* Block on the analog-SPI busy bit of <idx> (ANA_REG0 -> 0, ANA_REG9 -> 9).
 * Mirrors sys_ll_set_analog_reg_value's wait.  Bounded by callers in the
 * post-scheduler path via the shared delay budget; the early-boot caller
 * (bk7258_clock.c) bounds it separately. */
static inline void bk7258_ana_wait(unsigned idx)
{
  while ((BK7258_REG(BK7258_ANA_SPI_STATE) & BK7258_ANA_SPI_BUSY(idx)) != 0)
    {
    }
}

/* Bus-independent coarse microsecond delay.  One volatile MMIO read per
 * iteration so the compiler cannot elide it.  Sized for the slowest clock
 * relevant path (26 MHz cold residue); at higher post-switch clocks the
 * same count is a longer real wait, which is safe (it is a conservative
 * minimum settle). */
static inline void bk7258_clk_sleep_us(uint32_t us)
{
  uint32_t iters = us * BK7258_CLK_DELAY_ITERS_PER_US;
  while (iters-- != 0)
    {
      (void)BK7258_REG(BK7258_ANA_SPI_STATE);
    }
}

/* RMW an ANA_REG9 field through the spi_latch1v gate, exactly as the SDK's
 * sys_hal_ctrl_vddd_h_vol / sys_hal_ctrl_vdddig_h_vol do (sys_hal.c:517-542):
 * latch ON -> set field -> latch OFF, with the analog-SPI busy wait after
 * each write and a settle delay.  <clear>/<set> are bit-aligned field masks.
 */
static inline void bk7258_ana9_set_field(uint32_t clear, uint32_t set)
{
  BK7258_REG(BK7258_ANA_REG9) |= BK7258_ANA9_SPI_LATCH1V;
  bk7258_ana_wait(9);

  BK7258_REG(BK7258_ANA_REG9) =
      (BK7258_REG(BK7258_ANA_REG9) & ~clear) | set;
  bk7258_ana_wait(9);

  BK7258_REG(BK7258_ANA_REG9) &= ~BK7258_ANA9_SPI_LATCH1V;
  bk7258_ana_wait(9);
}

#endif /* __ARCH_ARM_SRC_BK7258_CHIP_BK7258_CLK_LL_H */

/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_dvfs.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * BK7258 (T5-AI) runtime CPU-frequency switching (DVFS) -- NuttX overlay
 * lower half.  Mirrors the Armino SDK runtime clock path:
 *
 *   sys_drv_switch_cpu_bus_freq(target)        (sys_ps_driver.c:244-289)
 *     loop prev远近 target, each step calls
 *     sys_hal_switch_cpu_bus_freq_low_to_high(i)  (sys_hal.c:620-686) or
 *     sys_hal_switch_cpu_bus_freq_high_to_low(i)  (sys_hal.c:548-619)
 *       which does: ctrl_vddd_h_vol(vddd) + ctrl_vdddig_h_vol(vddig)
 *                   core_bus_clock_ctrl(cksel, clkdiv_core, ckdiv_bus,
 *                                       ckdiv_cpu0, ckdiv_cpu1)
 *
 * This is a *runtime* API: the bootloader's boot_clock.c deliberately
 * mirrors only sys_hal_early_init (DPLL enable + SPI recalibration, analog
 * side left at SDK default VDDIG=0xB) and does NOT pick a CPU frequency.
 * Any per-tier lift of VDDD/VDDIG happens here, one tier at a time, so the
 * voltage rails move monotonically (no abrupt jump), exactly as the SDK
 * sys_drv_switch_cpu_bus_freq models.
 *
 * Following the NuttX lc823450 DVFS precedent (arch/arm/src/lc823450/
 * lc823450_dvfs2.c): a single standalone *_dvfs_set_freq(), not the NuttX PM
 * state machine.  No CONFIG_PM, no governor, no SCHED_HPWORK.
 *
 * The whole per-tier switch (voltage -> dividers -> mux -> SysTick reload)
 * is atomic with respect to interrupts via irqsave()/irqrestore(): an ISR
 * between the M1 write and the SysTick reload would observe an inconsistent
 * tick period.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_BK7258_DVFS

#include <stdint.h>
#include <errno.h>

#include <arch/irq.h>
#include <nuttx/clock.h>

#include "bk7258_clk_ll.h"
#include "bk7258_dvfs.h"
#include "bk7258_clockdiag.h"

/****************************************************************************
 * Private types
 ****************************************************************************/

/* One operating-point tier.  Fields map 1:1 to the SDK case table in
 * sys_hal.c:548-686.  <vddd> is the vdighsel field value (3 bits, the 3-bit
 * raw the SDK passes to sys_hal_ctrl_vddd_h_vol), <vddig> the vcorehsel
 * field value (4 bits raw passed to sys_hal_ctrl_vdddig_h_vol).
 */
struct bk7258_dvfs_step_s
{
  uint8_t  cksel_core;    /* M1 cksel_core [5:4]                */
  uint8_t  clkdiv_core;   /* M1 clkdiv_core [3:0]               */
  uint8_t  cpu0_speed;    /* CPU0_INT_HALT_CLK_OP cpu0_speed [4]: 0=/1, 1=/2 */
  uint8_t  vddd;          /* vdighsel raw (VDDD)                */
  uint8_t  vddig;         /* vcorehsel raw (VDDIG)              */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Tier table -- one entry per BK7258_FREQ_*.  Order MUST be ascending
 * (bk7258_dvfs_set_freq() steps ++/-- between prev and target).
 *
 * Values are the SDK-defined operating points (sys_hal.c:548-686 case fields
 * for PM_CPU_FRQ_26M..480M), unconditionally the non-DCO / non-ATE branch
 * because our port does not enable DCO_CLK.  The cpu0_speed field value
 * matches sys_hal_cpu_clk_div_set(0, ckdiv_cpu0): for every tier the SDK
 * passes ckdiv_cpu0 = 0x1 to set cpu0_speed = 1 (/2 halt divider at high
 * tiers to keep the bus < 240 MHz); the 26 MHz tier sets ckdiv_cpu0 = 0x1
 * too.  We keep cpu0_speed = 1 throughout (SysTick runs at the resulting
 * CPU0 processor clock; bk7258_clockdiag_current_cpu_hz() reports the
 * effective frequency for these M1/cpu0_speed combinations).
 *
 * Note (the "SDK 320 tier -> cpu0=160m" caveat, see bk7258_dvfs.h): the
 * 320 tier here yields CPU0 = 160 MHz at runtime; this is the SDK-aligned
 * stable top for CPU0 in this single-core port. */
static const struct bk7258_dvfs_step_s g_bk7258_dvfs_steps[] =
{
  /* tier 0:  26  MHz  cksel=0x0 clkdiv=0x0  VDDD=0x6 VDDIG=0xB */
  [BK7258_FREQ_26M]  = { 0x0, 0x0, 0x1, 0x6, 0xB },
  /* tier 1:  60  MHz  cksel=0x3 clkdiv=0x7  VDDD=0x6 VDDIG=0xB */
  [BK7258_FREQ_60M]  = { 0x3, 0x7, 0x1, 0x6, 0xB },
  /* tier 2:  80  MHz  cksel=0x3 clkdiv=0x5  VDDD=0x6 VDDIG=0xB */
  [BK7258_FREQ_80M]  = { 0x3, 0x5, 0x1, 0x6, 0xB },
  /* tier 3: 120 MHz  cksel=0x3 clkdiv=0x3  VDDD=0x6 VDDIG=0xC */
  [BK7258_FREQ_120M] = { 0x3, 0x3, 0x1, 0x6, 0xC },
  /* tier 4: 240 MHz  cksel=0x3 clkdiv=0x1  VDDD=0x6 VDDIG=0xD */
  [BK7258_FREQ_240M] = { 0x3, 0x1, 0x1, 0x6, 0xD },
  /* tier 5: 320 MHz (CPU0=160)  cksel=0x2 clkdiv=0x0  VDDD=0x7 VDDIG=0xD */
  [BK7258_FREQ_320M] = { 0x2, 0x0, 0x1, 0x7, 0xD },
};

/* Current tier.  Initialised to 26 MHz -- the boot_clock.c / loader residue
 * leaves the DPLL off and the core on the 26 MHz XTALH on cold reset; the
 * loader's --reboot 1 residue (M1=0x423, cksel=2/cdiv=3, DPLL on, ~80 MHz)
 * is a different entry state but the offset of the 80 MHz tier makes the
 * first up-step from 26 -> 80 still monotone once bk7258_dvfs_set_freq()
 * reads the case from bk7258_clockdiag_last_clock_case() on first call.
 *
 * We avoid trusting an unknown entry residue by NOT updating this from a
 * probe; the first caller (bk7258_clock_bringup_320m via
 * bk7258_dvfs_set_freq(320M)) explicitly declares the boot-time target and
 * we step from BK7258_FREQ_26M upward.  If the live clock is already higher
 * (loader residue) the up-steps are no-ops as far as the voltage program is
 * concerned -- a same-tier step is short-circuited in set_freq. */

static int g_bk7258_dvfs_cur = BK7258_FREQ_26M;

/****************************************************************************
 * Private: ANA_REG9 voltage setters (mirror SDK sys_hal_ctrl_vddd(_ig)_h_vol)
 ****************************************************************************/

/* Write the vdighsel field (VDDD) of ANA_REG9 to <v>.  Latch + settle exactly
 * per sys_hal_ctrl_vddd_h_vol (sys_hal.c:517-529). */
static void bk7258_ctrl_vddd_h_vol(uint8_t v)
{
  uint32_t set = (uint32_t)v << BK7258_ANA9_VDDD_SHIFT;
  bk7258_ana9_set_field(BK7258_ANA9_VDDD_MASK, set);
  bk7258_clk_sleep_us(BK7258_VDD_SETTLE_US);
}

static void bk7258_ctrl_vdddig_h_vol(uint8_t v)
{
  uint32_t set = (uint32_t)v << BK7258_ANA9_VDDDIG_SHIFT;
  bk7258_ana9_set_field(BK7258_ANA9_VDDDIG_MASK, set);
  bk7258_clk_sleep_us(BK7258_VDD_SETTLE_US);
}

/****************************************************************************
 * Private: core/bus mux control (mirror SDK sys_hal_core_bus_clock_ctrl)
 *
 * SDK low_to_high ordering (sys_hal.c:483-512): when going UP first set the
 * cpu0 divider (avoid bus > 240 M at clkdiv_core == 0), then clkdiv_core,
 * then cpu0/cpu1 dividers, then cksel last; barriers afterwards.  We mirror
 * that for the up direction; the down mirror reorders exactly the SDK way
 * (sys_hal_high_to_low cortex-low-to-high handles low_to_high separately).
 *
 * Our port is single-core CPU0 (cpu1 not used), so the cpu1 divider write is
 * omitted and cpu0_speed comes from the tier table.
 ****************************************************************************/

static void bk7258_write_cpu0_speed(uint8_t cpu0_speed)
{
  uint32_t v = BK7258_REG(BK7258_CPU0_HALT_CLK_OP);
  if (cpu0_speed)
    {
      v |= BK7258_CPU0_SPEED_BIT;
    }
  else
    {
      v &= ~BK7258_CPU0_SPEED_BIT;
    }
  BK7258_REG(BK7258_CPU0_HALT_CLK_OP) = v;
}

static void bk7258_write_m1(uint8_t cksel_core, uint8_t clkdiv_core)
{
  uint32_t v = BK7258_REG(BK7258_CPU_CLK_DIV_MODE1);
  v = (v & ~BK7258_M1_CLKDIV_MASK) | (clkdiv_core & BK7258_M1_CLKDIV_MASK);
  v = (v & ~BK7258_M1_CKSEL_MASK)  |
      ((uint32_t)cksel_core << BK7258_M1_CKSEL_SHIFT);
  BK7258_REG(BK7258_CPU_CLK_DIV_MODE1) = v;
}

/* Low-to-high tier switch: lift VDDD then VDDIG (when the target voltage is
 * higher than the current), then re-order the dividers before the mux. */
static void bk7258_dvfs_step_low_to_high(const struct bk7258_dvfs_step_s *s)
{
  /* SDK sys_hal_switch_cpu_bus_freq_low_to_high raises VDDD/VDDIG first,
   * then core_bus_clock_ctrl.  We lift VDDD, then VDDIG. */
  bk7258_ctrl_vddd_h_vol(s->vddd);
  bk7258_ctrl_vdddig_h_vol(s->vddig);

  /* core_bus_clock_ctrl up ordering: clkdiv_core==0 path writes the cpu
   * divider first (avoid bus > 240 M), then clkdiv_core, then cksel. */
  if (s->clkdiv_core == 0)
    {
      bk7258_write_cpu0_speed(s->cpu0_speed);
    }

  bk7258_write_m1(s->cksel_core, s->clkdiv_core);

  if (s->clkdiv_core != 0)
    {
      bk7258_write_cpu0_speed(s->cpu0_speed);
    }

  __asm__ volatile ("dsb 0xf" ::: "memory");
  __asm__ volatile ("isb 0xf" ::: "memory");
}

/* High-to-low tier switch: switch mux/dividers first, then lower VDDIG/VDDD
 * (per SDK sys_hal_switch_cpu_bus_freq_high_to_low ordering). */
static void bk7258_dvfs_step_high_to_low(const struct bk7258_dvfs_step_s *s)
{
  /* SDK high_to_low ordering: cksel first, then dividers, then voltages. */
  bk7258_write_cpu0_speed(s->cpu0_speed);
  bk7258_write_m1(s->cksel_core, s->clkdiv_core);

  __asm__ volatile ("dsb 0xf" ::: "memory");
  __asm__ volatile ("isb 0xf" ::: "memory");

  /* Lower VDDIG, then VDDD. */
  bk7258_ctrl_vdddig_h_vol(s->vddig);
  bk7258_ctrl_vddd_h_vol(s->vddd);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_dvfs_set_freq
 ****************************************************************************/

int bk7258_dvfs_set_freq(int tier)
{
  int prev;
  irqstate_t flags;
  int i;

  if (tier < BK7258_FREQ_MIN || tier > BK7258_FREQ_MAX)
    {
      return -EINVAL;
    }

  /* The whole step sequence is atomic wrt ISRs: an IRQ between the mux
   * write and the trailing SysTick reload would observe an inconsistent
   * tick period, and an IRQ inside the analog-SPI sequence can lose a
   * write to the analog block. */
  flags = irqsave();

  prev = g_bk7258_dvfs_cur;
  if (prev != tier)
    {
      if (tier > prev)
        {
          for (i = prev + 1; i <= tier; i++)
            {
              bk7258_dvfs_step_low_to_high(&g_bk7258_dvfs_steps[i]);
            }
        }
      else
        {
          for (i = prev - 1; i >= tier; i--)
            {
              bk7258_dvfs_step_high_to_low(&g_bk7258_dvfs_steps[i]);
            }
        }

      g_bk7258_dvfs_cur = tier;

      /* SysTick is clocked at the CPU0 processor clock; recompute the
       * one-tick reload so the tick period matches the new frequency.
       * This must happen before interrupts are re-enabled. */
      bk7258_systick_recalc();
    }

  irqrestore(flags);
  return 0;
}

int bk7258_dvfs_get_freq(void)
{
  return g_bk7258_dvfs_cur;
}

#endif /* CONFIG_BK7258_DVFS */

