56	__attribute__((used))
57	const struct fal_partition fal_partition_table[] = {
58	    { FAL_PART_MAGIC, "bootloader", "beken_onchip_crc", 0x00000L, 0x10000L, 0u },
59	    { FAL_PART_MAGIC, "app",        "beken_onchip_crc", 0x10000L, 0x10000L, 0u },
60	};
