63	/* ------------------------------------------------------------------ */
64	/* UART output (self-implemented; correct nibble order, no v>>32 UB).  */
65	/* ------------------------------------------------------------------ */
66	static void uart_putc(char c)
67	{
68	    /*
69	     * Poll bit20 (TX-FIFO-not-full). The poll is bounded: if the bit polarity
70	     * is ever inverted on silicon, we degrade gracefully to the same
71	     * write-through behavior the verified minimal bootloader used, rather
72	     * than hanging the boot.
73	     */
74	    for (int i = 0; i < 100000; i++) {
75	        if (UART1_STATUS & UART1_TX_READY) {
76	            break;
77	        }
78	    }
79	    UART1_FIFO = (uint32_t)(uint8_t)c;
80	}
81	
82	static void uart_puts(const char *s)
83	{
84	    while (*s) {
85	        uart_putc(*s++);
86	    }
87	}
88	
89	static void print_hex32(uint32_t v)
90	{
91	    static const char hex[] = "0123456789ABCDEF";
92	    int s;
93	    /* for(s=28; s>=0; s-=4): avoids the v>>32 undefined behaviour that the
94	       earlier probe fell into (top nibble got shifted into oblivion). */
95	    for (s = 28; s >= 0; s -= 4) {
96	        uart_putc(hex[(v >> s) & 0xFu]);
97	    }
98	}
99	
100	static void log_u32(const char *label, uint32_t value)
101	{
102	    uart_puts(label);
103	    uart_puts("0x");
104	    print_hex32(value);
105	    uart_puts("\r\n");
106	}
