108	/* ------------------------------------------------------------------ */
109	/* Partition scan + helpers.                                          */
110	/* ------------------------------------------------------------------ */
111	static int name_eq(const char *a, const char *b)
112	{
113	    int i;
114	    for (i = 0; i < FAL_DEV_NAME_MAX; i++) {
115	        if (a[i] != b[i]) {
116	            return 0;
117	        }
118	        if (a[i] == '\0') {
119	            return 1;
120	        }
121	    }
122	    return 1;   /* equal across the full FAL_DEV_NAME_MAX width */
123	}
124	
125	static const struct fal_partition *fal_find(const char *name)
126	{
127	    size_t i;
128	    for (i = 0; i < FAL_PART_COUNT; i++) {
129	        if (fal_partition_table[i].magic_word != FAL_PART_MAGIC) {
130	            continue;
131	        }
132	        if (name_eq(fal_partition_table[i].name, name)) {
133	            return &fal_partition_table[i];
134	        }
135	    }
136	    return (const struct fal_partition *)0;
137	}
138	
139	/* ------------------------------------------------------------------ */
140	/* App header validation (ported from bk7236_min_bl.S to C).          */
141	/* ------------------------------------------------------------------ */
142	static int validate_app(uint32_t app_vec)
143	{
144	    volatile uint32_t *vec   = (volatile uint32_t *)app_vec;
145	    volatile uint32_t *magic = (volatile uint32_t *)(app_vec + 0x100u);
146	    uint32_t msp  = vec[0];
147	    uint32_t rst  = vec[1];
148	
149	    /* MSP must land in SRAM [0x28000000 .. 0x280A0000]. */
150	    if (msp < 0x28000000u || msp > 0x280A0000u) {
151	        uart_puts("BAD\r\nmsp OOR\r\n");
152	        return 0;
153	    }
154	    /* Reset_Handler must have the Thumb bit set. */
155	    if ((rst & 1u) == 0u) {
156	        uart_puts("BAD\r\nreset no-thumb\r\n");
157	        return 0;
158	    }
159	    /* app magic @ app_vec + 0x100 == "BK7236\0\0"
160	       bytes  42 4B 37 32 -> word 0x32374B42
161	              33 36 00 00 -> word 0x00003633 */
162	    if (magic[0] != 0x32374B42u) {
163	        uart_puts("BAD\r\nmagic0\r\n");
164	        return 0;
165	    }
166	    if (magic[1] != 0x00003633u) {
167	        uart_puts("BAD\r\nmagic1\r\n");
168	        return 0;
169	    }
170	    return 1;
171	}
172	
173	/* ------------------------------------------------------------------ */
174	/* C entry called from start.S. Returns app logical vector address.   */
175	/* ------------------------------------------------------------------ */
176	__attribute__((used))
177	uint32_t c_main(void)
178	{
179	    const struct fal_partition *app;
180	    uint32_t app_vec;
181	
182	    uart_puts("u_bootloader enter\r\n");
183	
184	    /* Cold-start DPLL enable + flash clock init.  On cold reset the BootROM
185	     * leaves EN_DPLL=0; this mirrors the Armino SDK early-init sequence to
186	     * bring the DPLL up and set the flash clock, using the chip-id-specific
187	     * ANA_REG values for this board (MP_C = default branch).
188	     * If this hangs, the watchdog or J-Link recovery restores the previous
189	     * bootloader; if it succeeds the app sees DPLL on and can switch to
190	     * 320 MHz via its own bring-up path.
191	     */
192	
193	    boot_clock_cold_init();
194	
195	    /* A: FAL partition parse -> find "app". */
196	    app = fal_find("app");
197	    if (app == (const struct fal_partition *)0) {
198	        uart_puts("BAD\r\nno app part\r\n");
199	        for (;;) { }
200	    }
201	    app_vec = FLASH_BASE + (uint32_t)app->offset;
202	    log_u32("partition app @ ", app_vec);
203	
204	    /* Validate app header. */
205	    if (!validate_app(app_vec)) {
206	        for (;;) { }
207	    }
208	
209	    log_u32("jump to:", app_vec);
210	    uart_puts("JMP\r\n");
211	    return app_vec;
212	}
