/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_wdt.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * BK7258 (T5-AI) hardware watchdog NuttX lower-half driver.
 *
 * Full WDT BSP, mirroring the Armino SDK WDT driver path
 * (cp/middleware/driver/wdt/wdt_driver.c + wdt_hal.c + wdt_ll.h):
 *
 *   SDK path                          NuttX equivalent
 *   ─────────────────────────────     ──────────────────────────
 *   bk_wdt_driver_init()              bk7258_wdt_initialize()
 *     wdt_hal_init()                    (select APB WDT, no AON switching)
 *     bk_timer_start(TIMER_ID2,...)     (NuttX automonitor handles feed)
 *     aon_pmu_drv_wdt_rst_dev_enable() (already done by bootloader)
 *   bk_wdt_start(timeout_ms)          bk7258_wdt_start()
 *     wdt_init_common()                 (WDT clock already on)
 *     wdt_hal_init_wdt → set_period     key1+period, key2+period
 *   bk_wdt_feed()                     bk7258_wdt_keepalive()
 *     wdt_hal_init_wdt(hal, period)     (= reinit with same period)
 *   bk_wdt_stop()                     bk7258_wdt_stop()
 *     close_wdt()                       key1+period=0, key2+period=0
 *
 * NuttX watchdog upper-half (CONFIG_WATCHDOG_AUTOMONITOR) handles periodic
 * feeding via work queue once /dev/watchdog0 is opened and started.
 * We do not need a separate TIMER_ID2 or IRQ-based feed loop.
 *
 * The bootloader arms the APB WDT with period=8000 (~8 s) during cold-init.
 * This driver reinitializes the WDT with the same or user-configured period
 * and keeps it alive.  The bootloader does NOT close WDT before jumping
 * (matching vendor behavior: sub_200176C has no WDT close code).
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_BK7258_WDT

#include <stdint.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/timers/watchdog.h>

#include "bk7258_wdt.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* APB WDT register addresses (wdt_reg.h, wdt_struct.h). */

#define BK7258_WDT_BASE           0x44800000u
#define BK7258_WDT_GLOBAL_CTRL    (BK7258_WDT_BASE + 0x08u)
#define BK7258_WDT_CTRL           (BK7258_WDT_BASE + 0x10u)  /* period+key */

/* SYS block (for SYS_CTRL WDT clock/reset config, matching bootloader). */

#define BK7258_SYS_CTRL_REG       0x44000008u

/* WDT key values (wdt_reg.h:35-36). */

#define BK7258_WDT_KEY1           0x5Au
#define BK7258_WDT_KEY2           0xA5u

/* WDT field masks (wdt_reg.h). */

#define BK7258_WDT_PERIOD_MASK    0xFFFFu
#define BK7258_WDT_KEY_SHIFT      16

/* Default timeout: 8000 ms (matches SDK CONFIG_INT_WDT_PERIOD_MS and
 * bootloader's WDT_PERIOD).  The WDT clock is ~1 kHz, so period in the
 * register is approximately milliseconds. */

#define BK7258_WDT_DEFAULT_TIMEOUT_MS  8000u

/* SYS_CTRL bits[5:0] = 0x26: vendor WDT clock/reset config. */

#define BK7258_WDT_SYSCTRL_MASK   0x3Fu
#define BK7258_WDT_SYSCTRL_VAL    0x26u

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct bk7258_wdt_lowerhalf_s
{
  struct watchdog_lowerhalf_s wdt_lh;  /* Must be first */
  uint32_t timeout;                    /* Current timeout in ms */
  bool     started;                    /* WDT is armed */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int bk7258_wdt_start(struct watchdog_lowerhalf_s *lower);
static int bk7258_wdt_stop(struct watchdog_lowerhalf_s *lower);
static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower);
static int bk7258_wdt_getstatus(struct watchdog_lowerhalf_s *lower,
                                struct watchdog_status_s *status);
static int bk7258_wdt_settimeout(struct watchdog_lowerhalf_s *lower,
                                 uint32_t timeout);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct watchdog_ops_s g_bk7258_wdt_ops =
{
  .start      = bk7258_wdt_start,
  .stop       = bk7258_wdt_stop,
  .keepalive  = bk7258_wdt_keepalive,
  .getstatus  = bk7258_wdt_getstatus,
  .settimeout = bk7258_wdt_settimeout,
};

static struct bk7258_wdt_lowerhalf_s g_bk7258_wdt;

/****************************************************************************
 * Private Helpers
 ****************************************************************************/

/* Write the two-step key sequence to WDT_CTRL (mirrors wdt_ll_set_period).
 * The first write with key1 unlocks; the second with key2 applies the period. */

static inline void bk7258_wdt_write_period(uint32_t period)
{
  putreg32((BK7258_WDT_KEY1 << BK7258_WDT_KEY_SHIFT) |
           (period & BK7258_WDT_PERIOD_MASK),
           BK7258_WDT_CTRL);

  putreg32((BK7258_WDT_KEY2 << BK7258_WDT_KEY_SHIFT) |
           (period & BK7258_WDT_PERIOD_MASK),
           BK7258_WDT_CTRL);
}

/****************************************************************************
 * Private: lower-half operations
 ****************************************************************************/

static int bk7258_wdt_start(struct watchdog_lowerhalf_s *lower)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  /* Ensure SYS_CTRL WDT config (bootloader already did this, but be
   * defensive: if NuttX is entered via a path that skipped the bootloader,
   * the WDT clock might not be configured). */

  uint32_t v = getreg32(BK7258_SYS_CTRL_REG);
  v = (v & ~BK7258_WDT_SYSCTRL_MASK) | BK7258_WDT_SYSCTRL_VAL;
  putreg32(v, BK7258_SYS_CTRL_REG);

  /* Soft-reset the WDT state machine (mirrors wdt_ll_set_period). */

  putreg32(1u, BK7258_WDT_GLOBAL_CTRL);

  /* Arm the WDT with the configured period. */

  bk7258_wdt_write_period(priv->timeout);

  priv->started = true;
  wdinfo("started, timeout=%" PRIu32 " ms\n", priv->timeout);
  return OK;
}

static int bk7258_wdt_stop(struct watchdog_lowerhalf_s *lower)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  /* Disarm: key sequence with period=0 (mirrors wdt_hal_close for BK7236,
   * wdt_hal.c:116-125). */

  putreg32(1u, BK7258_WDT_GLOBAL_CTRL);
  putreg32(BK7258_WDT_KEY1 << BK7258_WDT_KEY_SHIFT, BK7258_WDT_CTRL);
  putreg32(BK7258_WDT_KEY2 << BK7258_WDT_KEY_SHIFT, BK7258_WDT_CTRL);

  priv->started = false;
  wdinfo("stopped\n");
  return OK;
}

/* keepalive = reinit with same period (SDK bk_wdt_feed = wdt_hal_init_wdt
 * with same period, wdt_driver.c:172-180). */

static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  bk7258_wdt_write_period(priv->timeout);
  return OK;
}

static int bk7258_wdt_getstatus(struct watchdog_lowerhalf_s *lower,
                                struct watchdog_status_s *status)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  status->flags = WDFLAGS_RESET;
  if (priv->started)
    {
      status->flags |= WDFLAGS_ACTIVE;
    }

  status->timeout = priv->timeout;

  /* timeleft: we cannot read the current counter from the BK7258 APB WDT
   * (no readable counter register).  Return timeout as an upper bound. */

  status->timeleft = priv->timeout;
  return OK;
}

static int bk7258_wdt_settimeout(struct watchdog_lowerhalf_s *lower,
                                 uint32_t timeout)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  if (timeout > BK7258_WDT_PERIOD_MASK)
    {
      timeout = BK7258_WDT_PERIOD_MASK;
    }

  priv->timeout = timeout;

  /* If already running, re-arm with new period. */

  if (priv->started)
    {
      bk7258_wdt_write_period(priv->timeout);
    }

  wdinfo("timeout set to %" PRIu32 " ms\n", priv->timeout);
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_wdt_initialize
 *
 * Description:
 *   Initialize the BK7258 APB WDT and register as /dev/watchdog0.
 *   Mirrors the SDK bk_wdt_driver_init + bk_wdt_start path:
 *     - Select APB WDT (the bootloader already configured SYS_CTRL and
 *       AON/ABP WDT key sequences; we re-assert the config defensively).
 *     - Set default period (8 s, matching bootloader WDT_PERIOD).
 *     - Register the NuttX watchdog lower-half.
 *
 *   After registration, opening /dev/watchdog0 and calling start enables
 *   CONFIG_WATCHDOG_AUTOMONITOR (if configured), which feeds the WDT
 *   automatically via work queue.
 *
 *   Call this from board_app_initialize() (bk7258_bringup.c), after procfs
 *   mount and before DVFS or other long-running init.
 *
 ****************************************************************************/

int bk7258_wdt_initialize(void)
{
  struct bk7258_wdt_lowerhalf_s *priv = &g_bk7258_wdt;

  priv->wdt_lh.ops = &g_bk7258_wdt_ops;
  priv->timeout    = BK7258_WDT_DEFAULT_TIMEOUT_MS;
  priv->started    = false;

  /* The bootloader already armed the WDT (period=8000, SYS_CTRL=0x26).
   * We don't re-arm here — start() does that when the upper-half opens
   * the device.  This matches the SDK pattern where bk_wdt_driver_init
   * does NOT call bk_wdt_start; the caller decides when to arm. */

  watchdog_register("/dev/watchdog0",
                    (struct watchdog_lowerhalf_s *)priv);

  wdinfo("BK7258 WDT registered as /dev/watchdog0, default timeout=%" PRIu32
         " ms\n", priv->timeout);
  return OK;
}

#endif /* CONFIG_BK7258_WDT */

