static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower)
{
  struct bk7258_wdt_lowerhalf_s *priv =
    (struct bk7258_wdt_lowerhalf_s *)lower;

  /* Feed = clear status + reinit with same period.
   * Mirrors the bootloader's boot_wdt_feed() which clears APB_WDT
   * status bit[1:0] then writes key1+period, key2+period.
   * Do NOT soft_reset here — soft_reset clears the WDT clock config
   * (SYS_CTRL), and without reconfiguring SYS_CTRL afterwards the WDT
   * has no clock source.  The bootloader's feed (which works) does not
   * soft_reset either. */

  putreg32(getreg32(BK7258_WDT_STATUS) & ~0x3u, BK7258_WDT_STATUS);
  bk7258_wdt_write_period(priv->timeout);
  return OK;
}

