__IRAM_SEC void bk_task_wdt_start()
{
    s_task_wdt_enabled = true;
}

__attribute__((section(".itcm_sec_code"))) void bk_task_wdt_stop()
{
    s_task_wdt_enabled = false;
}

void bk_task_wdt_feed(void)
{
