   * (the SDK's wdt_init_common() re-powers the clock after soft_reset,
   * but we don't have that call in keepalive). */

  putreg32(getreg32(BK7258_WDT_STATUS) & ~0x3u, BK7258_WDT_STATUS);
  bk7258_wdt_write_period(priv->timeout);
  return OK;
}

